// === Tab: mySketch ===
const palettes = {
    "10 Core": ["#ffff00", "#ff88033", "#ff3333", "#ff00bb", "#9966ff", "#00dddd", "#66bcff", "#00e294", "#00ceff", "#99dd00"],
}

let ngons = [];
let cnv, palette, bgColor;
let transformShader, drawCanvas, shaderCanvas;

function preload() {
    transformShader = loadShader('https://openprocessing.org/sketch/2684153/files/shader.vert', 'transformations.frag');
}

function setup() {
    cnv = createCanvas(1000, 750);
    // cnv = createCanvas(windowWidth, windowHeight);

    shaderCanvas = createGraphics(width, height, WEBGL);
    shaderCanvas.noStroke();
    shaderCanvas.textureWrap(REPEAT);

    drawCanvas = createGraphics(1024, 1024);
		drawCanvas.pixelDensity(1);

    palette = palettes["10 Core"];
    shuffle(palette, true);
    bgColor = "#000";

    generateSquares();
}

function draw() {
    drawCanvas.background(bgColor);
    ngons.forEach(ngon => ngon.draw());

    shaderCanvas.shader(transformShader);
    transformShader.setUniform('texture', drawCanvas);
    transformShader.setUniform('time', millis() / 1000);

    shaderCanvas.rect(0, 0, shaderCanvas.width, shaderCanvas.height);

    let shaderDensity = shaderCanvas.pixelDensity();
    let shaderImg = createImage(shaderCanvas.width * shaderDensity, shaderCanvas.height * shaderDensity);
    shaderImg.copy(shaderCanvas, -shaderCanvas.width / 2, -shaderCanvas.height / 2, shaderCanvas.width, shaderCanvas.height, 0, 0, shaderCanvas.width * shaderDensity, shaderCanvas.height * shaderDensity);
    drawingContext.imageSmoothingQuality = "high"; // don't think this does anything
    image(shaderImg, 0, 0, width, height);
}

class NgonCell {
    constructor(pts) {
        this.verts = pts;
        this.lerpSpeed = random(1, 3);
        this.colorLerpSpeed = random(0.5, 2);
        this.colorOffset = random(TWO_PI);
        this.colors = shuffle(palette);
        this.c1 = color(this.colors[0]);
        this.c2 = color(this.colors[1]);
        this.center = this.findCenter();
    }

    findCenter() {
        const cx = this.verts.reduce((accumulator, object) => {
            return accumulator + object.x;
        }, 0) / this.verts.length;
        const cy = this.verts.reduce((accumulator, object) => {
            return accumulator + object.y;
        }, 0) / this.verts.length;
        return createVector(cx, cy);
    }

    draw() {
        drawCanvas.noFill();
        let inc = 0.05;
        let total = 8;
        for (let i = 0; i < total; i++) {
            let lerpVal = i / total;
            lerpVal = 0.05 + fract(lerpVal);
            drawCanvas.strokeWeight(map(lerpVal, 0, 1, 0.1, 2));
            drawCanvas.stroke(lerpColor(this.c1, this.c2, sin(lerpVal * 5 - frameCount / 10 * this.colorLerpSpeed + this.colorOffset) * 0.5 + 0.5));
            drawCanvas.beginShape();
            for (let vIdx = 0; vIdx < this.verts.length; vIdx++) {
                let ov = p5.Vector.lerp(this.verts[vIdx], this.center, lerpVal);
                if (ov.dist(this.center) < 4 * this.sideUnits) continue;
                drawCanvas.vertex(ov.x, ov.y);
            }
            drawCanvas.endShape(CLOSE);
        }
    }
}

function generateSquares() {
    for (let x = 0; x < drawCanvas.width; x += 64) {
        for (let y = 0; y < drawCanvas.width; y += 64) {
            const pts = [createVector(x, y), createVector(x + 64, y), createVector(x + 64, y + 64), createVector(x, y + 64)];
            ngons.push(new NgonCell(pts));
        }
    }
}

